                the admin to reach the drawer to verify. */}
            {isStaff && String(doc?.status || "") !== "draft" ? (
              <Button
                size="sm"
                variant="outline"
                onClick={() => setVersionDrawerOpen(true)}
                testid="doc-header-history-btn"
